var session=ModelSession.create('onDevice');session.toolSets=[];
if(!session.isAvailable){var result=session.respond('Return neutral.');if(result!==undefined||typeof session.lastError!=='string'||session.lastError.indexOf('unavailable')<0)throw new Error('Unavailable model did not report its error');editor.setText('Apple model unavailable: '+session.lastError);draft.update();}
else{editor.setText('Apple model pending neutral');draft.update();var result=session.respond('Return 2000 repetitions of the word neutral, separated by spaces.');if(session.lastError)throw new Error(session.lastError);editor.setText('Model response completed before cancellation');draft.update();}
